+uint64_t thread_start_cyc[THREAD_NUM];
+uint64_t cyc_start[4];
+uint64_t cyc_enter[4];
+uint64_t cyc_end[4];
+

 static void thread_entry(void *p1, void *p2, void *p3)
 {
@@ -25,8 +30,9 @@ static void thread_entry_prio(void *p1, void *p2, void *p3)
 {
