        tid_num[i++] = POINTER_TO_INT(p1);
 }

@@ -139,18 +145,22 @@ ZTEST(threads_scheduling_1cpu, test_priority_preemptible_wait_prio)
        tid[0] = k_thread_create(&tdata_prio[0], tstacks[0], STACK_SIZE,
